import {Injectable} from '@angular/core';
import {BehaviorSubject} from 'rxjs';
import { Cart, CartItem } from './models/cart.model';
import { Product } from './models/product.model';
import { environment } from '../environments/environment';

@Injectable({
    providedIn: 'root'
})
export class CartService {
    private readonly STORAGE_KEY = `${environment.storagePrefix}cart`;
    private cart: Cart = new Cart();
    private cartItemsSource = new BehaviorSubject<CartItem[]>([]);
    cartItems$ = this.cartItemsSource.asObservable();

    private initialCartItems: Product[] = [
        new Product(
            1,
            'Lightweight Hiking Backpack',
            'A comfortable and lightweight backpack perfect for hiking trips',
            75.00,
            'https://lh3.googleusercontent.com/aida-public/AB6AXuD7rwUAG22IusygVJfIO8Xs8xTRq3vWITg7BmFqW4dw3LF8jEo3AJM2tuVYTw019AyEFRoEzG53eEmgXGXG1M_QWfL8tDCTkIPUNdMbV8eyskU1q50VcsUg_GAaqScOFOG5Tk_1g-yFYOPwS2xiQFdgx0B42hNMocrC8Gv1cmJVXtx_Myu9-Oh7exxZJ3GvOhQ47IZ5oIBvX8W4RML8cUjb5K9PxP_QxW8NS-xX6coJGrEaEfkyD9ni5xo2umor3E8S67zrTnp64-rx',
            'Hiking',
            'OutdoorPro',
            true,
            10,
            4.5,
            28,
            ['Water-resistant', 'Multiple compartments', 'Padded straps'],
            ['Black', 'Green', 'Blue'],
            ['S', 'M', 'L']
        ),
        new Product(
            2,
            'Waterproof Travel Backpack',
            'A durable and waterproof backpack for all your travel needs',
            37.50,
            'https://lh3.googleusercontent.com/aida-public/AB6AXuBjkC3lQ32psfToXEkJe9qU22pDUC-Bt3nOR3q5syGWaWwdUSRAnbVLmuHuHsCjZdZNKk9QNkAwpuRi0PzgBTsmlnMxglyw2PbrpuwWTW7COvBGn9Cc_rv_fsSVzB3-4fz4GsQ2qoiajWPBIFAJbAm76X5-YF49tiddSXtFKyPOVLPwUxOG7i7Bv0VUIhoVDXsCmhFLRUWxMO1Zw-79gFU4Tav6ZlkbsoEHAnXJ42rc1ulIwDnewj8IRsjCnWWpW_aHMcmDhUPLfh0N',
            'Travel',
            'TravelMate',
            true,
            15,
            4.2,
            35,
            ['Waterproof', 'Laptop compartment', 'USB charging port'],
            ['Black', 'Navy', 'Gray'],
            ['M', 'L', 'XL']
        )
    ];    constructor() {
        this.loadCart();
        
        // If no cart in storage, initialize with some default items
        if (this.cart.items.length === 0) {
            this.initialCartItems.forEach(product => {
                this.cart.addItem(product);
            });
            this.saveCart();
        }
        
        this.cartItemsSource.next(this.cart.items);
    }

    getCartItems() {
        return this.cart.items;
    }

    addToCart(product: Product, quantity: number = 1) {
        this.cart.addItem(product, quantity);
        this.cartItemsSource.next([...this.cart.items]);
        this.saveCart();
        console.log('Product added to cart via service:', product);
    }

    removeItem(itemToRemove: CartItem | Product) {
        const productId = itemToRemove instanceof Product ? itemToRemove.id : itemToRemove.product.id;
        this.cart.removeItem(productId);
        this.cartItemsSource.next([...this.cart.items]);
        this.saveCart();
    }

    incrementItem(itemToIncrement: CartItem | Product) {
        const productId = itemToIncrement instanceof Product ? itemToIncrement.id : itemToIncrement.product.id;
        const item = this.cart.items.find(item => item.product.id === productId);
        if (item) {
            this.cart.updateQuantity(productId, item.quantity + 1);
            this.cartItemsSource.next([...this.cart.items]);
            this.saveCart();
        }
    }

    decrementItem(itemToDecrement: CartItem | Product) {
        const productId = itemToDecrement instanceof Product ? itemToDecrement.id : itemToDecrement.product.id;
        const item = this.cart.items.find(item => item.product.id === productId);
        
        if (item) {
            if (item.quantity > 1) {
                this.cart.updateQuantity(productId, item.quantity - 1);
            } else {
                this.cart.removeItem(productId);
            }
            this.cartItemsSource.next([...this.cart.items]);
            this.saveCart();
        }
    }    getSubtotal() {
        return this.cart.totalPrice;
    }

    getEstimatedTax() {
        return this.getSubtotal() * 0.10; // Assuming 10% tax
    }

    getTotal() {
        return this.getSubtotal() + this.getEstimatedTax();
    }

    clearCart() {
        this.cart.clear();
        this.cartItemsSource.next([]);
        this.saveCart();
    }

    private saveCart() {
        try {
            localStorage.setItem(this.STORAGE_KEY, JSON.stringify(this.cart.items.map(item => ({
                productId: item.product.id,
                quantity: item.quantity
            }))));
        } catch (err) {
            console.error('Error saving cart to localStorage', err);
        }
    }

    private loadCart() {
        try {
            const savedCart = localStorage.getItem(this.STORAGE_KEY);
            if (savedCart) {
                const cartItems = JSON.parse(savedCart);
                this.cart = new Cart();
                // We need to get the actual product objects from somewhere
                // For now, we'll just use our mock products
                cartItems.forEach((item: any) => {
                    const product = this.initialCartItems.find(p => p.id === item.productId);
                    if (product) {
                        this.cart.addItem(product, item.quantity);
                    }
                });
            }
        } catch (err) {
            console.error('Error loading cart from localStorage', err);
            this.cart = new Cart();
        }
    }
}
